#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

#
# The move of the live app to the shared Cloudflare account, in three parts run on different days:
#   bash scripts/move-to-shared-account/move.sh prepare           anyone in the shared account, days before
#   bash scripts/move-to-shared-account/move.sh evening [stage]   ymsrubio, at the announced quiet hour
#   bash scripts/move-to-shared-account/move.sh cleanup           ymsrubio, 7 days after keeping the move
# The order and the reasons: README.md here, and https://github.com/isayulee/CSA-ID/issues/95.
# .move.env (git-ignored) remembers the public values between runs. Secrets are never written to disk.

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO="$(cd "$HERE/../.." && pwd)"
OUT="$HERE/out"
WR="${WRANGLER:-$REPO/node_modules/.bin/wrangler}"
WHERE=--remote
OLD_CFG="$OUT/old.jsonc"
NEW_CFG="$REPO/wrangler.jsonc"
# The live app before the move, in ymsrubio's personal account (wrangler.jsonc as it was until the move).
OLD_ORIGIN="https://csa-id.yuanmiguelrubio.workers.dev"
OLD_D1_ID="e10ae114-9102-4133-8305-b349f5497788"
OLD_KV_ID="0ff2270b1f6e431fb53814834f29cd30"
# shellcheck source=lib.sh
source "$HERE/lib.sh"

show() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; }
# must "what to do if it fails" COMMAND...: run COMMAND, or explain and stop.
must() { local help="$1"; shift; show "$*"; if ! "$@"; then warn "$help"; exit 1; fi; }
# load KEY...: the values an earlier run saved in .move.env (empty when there are none).
load() { local k; for k in "$@"; do printf -v "$k" '%s' "$(_existing "$k" || true)"; done; }
# ask_valid KEY "Prompt" REGEX "hint": ask until the answer matches.
ask_valid() {
  local key="$1" prompt="$2" pattern="$3" hint="$4"
  while true; do
    ask "$key" "$prompt" || exit 1
    [[ "${!key}" =~ $pattern ]] && return 0
    warn "$hint"
  done
}
new_origin() { printf 'https://csa-id.%s.workers.dev' "$NEW_SUBDOMAIN"; }
# jsonc_values KEY: the distinct "KEY": "value" values in wrangler.jsonc.
jsonc_values() { grep -o -E "\"$1\" *: *\"[^\"]*\"" "$NEW_CFG" | sed -E 's/.*: *"([^"]*)"$/\1/' | sort -u; }
when() { node -e 'console.log(new Date(Number(process.argv[1]) * 1000).toLocaleString())' "$1"; }
UUID='^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
HEX32='^[0-9a-f]{32}$'

write_old_config() {
  mkdir -p "$OUT"
  cat > "$OLD_CFG" <<EOF
// Generated by move.sh: ymsrubio's personal account, where the live app ran before the move.
{
  "name": "csa-id",
  "account_id": "$OLD_ACCOUNT_ID",
  "d1_databases": [{ "binding": "DB", "database_name": "csa-id", "database_id": "$OLD_D1_ID" }],
  "kv_namespaces": [{ "binding": "KV", "id": "$OLD_KV_ID" }]
}
EOF
}

write_redirect_config() {
  cat > "$OUT/redirect.jsonc" <<EOF
// Generated by move.sh: the old account's csa-id Worker, turned into a redirect to the new address.
{
  "name": "csa-id",
  "account_id": "$OLD_ACCOUNT_ID",
  "main": "../redirect-worker/index.mjs",
  "compatibility_date": "2026-11-01",
  "workers_dev": true,
  "vars": { "TARGET_ORIGIN": "$(new_origin)" }
}
EOF
}

# ── Part 1 · prepare ──────────────────────────────────────────────────────

prepare() {
TOTAL_STAGES=6
banner "CSA-ID move · Part 1 of 3: prepare the shared account"
# Wrangler creates things from an empty folder, so it never offers to edit wrangler.jsonc.
local empty log
empty=$(mktemp -d)
log=$(mktemp)

stage "Sign in and pick the shared account"
say "This part creates the app's database, KV namespace and Turnstile widget in the shared team"
say "account. Nothing goes live, and nothing here touches ymsrubio's personal account."
if ! "$WR" whoami --json >/dev/null 2>&1; then
  step "Wrangler isn't signed in yet. A browser opens: sign in to Cloudflare and allow access."
  must "Sign-in failed. Run npx wrangler login, then this part again." "$WR" login
fi
show "wrangler whoami"
"$WR" whoami || true
step "Find the shared team account in the list above and copy its Account ID."
ask_valid NEW_ACCOUNT_ID "Shared account's Account ID:" "$HEX32" "An Account ID is 32 characters of 0-9 and a-f."
write_env NEW_ACCOUNT_ID "$NEW_ACCOUNT_ID"
export CLOUDFLARE_ACCOUNT_ID="$NEW_ACCOUNT_ID"
pause

stage "Settle the workers.dev subdomain"
say "Every NFC Card will hold https://csa-id.<subdomain>.workers.dev/id/<slug>. Choose the subdomain"
say "now: changing it later means rewriting every card again."
open_url "https://dash.cloudflare.com/$NEW_ACCOUNT_ID/workers-and-pages"
step "On the Workers & Pages page, find \"Your subdomain\"."
step "Keep it, or select Change and pick a short name that will last, like the CSA team's."
ask_valid NEW_SUBDOMAIN "The subdomain, without .workers.dev:" '^[a-z0-9]([a-z0-9-]*[a-z0-9])?$' \
  "Lowercase letters, digits and inner hyphens only."
write_env NEW_SUBDOMAIN "$NEW_SUBDOMAIN"
say "The live address will be $(new_origin)."
pause

stage "Create the D1 database"
load NEW_D1_ID
if [[ -n "$NEW_D1_ID" ]]; then
  note "Already created in an earlier run: $NEW_D1_ID"
else
  say "Creates the csa-id database in the shared account, in Asia Pacific, near Manila."
  confirm "Create it now?" || { warn "Stopped. Run this part again when you're ready."; exit 1; }
  show "wrangler d1 create csa-id --location apac"
  "$WR" d1 create csa-id --location apac --cwd "$empty" | tee "$log" || true
  NEW_D1_ID=$(grep -o -E '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}' "$log" | head -n 1 || true)
  if [[ -z "$NEW_D1_ID" ]]; then
    warn "Couldn't read the new database's ID. If csa-id already existed, find it here:"
    "$WR" d1 list --cwd "$empty" || true
    ask_valid NEW_D1_ID "csa-id's database ID:" "$UUID" "A database ID looks like 0a1b2c3d-0a1b-4c2d-8e3f-0a1b2c3d4e5f."
  fi
  write_env NEW_D1_ID "$NEW_D1_ID"
fi
pause

stage "Create the KV namespace"
load NEW_KV_ID
if [[ -n "$NEW_KV_ID" ]]; then
  note "Already created in an earlier run: $NEW_KV_ID"
else
  say "Creates the csa-id KV namespace, where Profile images live."
  confirm "Create it now?" || { warn "Stopped. Run this part again when you're ready."; exit 1; }
  show "wrangler kv namespace create csa-id"
  "$WR" kv namespace create csa-id --cwd "$empty" | tee "$log" || true
  NEW_KV_ID=$(grep -o -E '"?id"? *[:=] *"[0-9a-f]{32}"' "$log" | grep -o -E '[0-9a-f]{32}' | head -n 1 || true)
  if [[ -z "$NEW_KV_ID" || "$NEW_KV_ID" == "$NEW_ACCOUNT_ID" ]]; then
    warn "Couldn't read the new namespace's ID. If csa-id already existed, find it here:"
    "$WR" kv namespace list --cwd "$empty" || true
    ask_valid NEW_KV_ID "csa-id's namespace ID:" "$HEX32" "A namespace ID is 32 characters of 0-9 and a-f."
  fi
  write_env NEW_KV_ID "$NEW_KV_ID"
fi
pause

stage "Create the Turnstile widget"
say "Turnstile protects the Abuse Report form. The widget covers the live site and every preview."
open_url "https://dash.cloudflare.com/$NEW_ACCOUNT_ID/turnstile"
step "Select Add widget."
step "Widget name: csa-id. Region: Rest of World."
step "Hostname management: add $NEW_SUBDOMAIN.workers.dev (it covers all of its subdomains)."
step "Widget mode: Managed. Leave pre-clearance off, then select Create."
step "Copy the Site Key."
ask_valid TURNSTILE_SITE_KEY "Site Key (public):" '^0x[A-Za-z0-9_-]{10,}$' "A Site Key starts with 0x."
write_env TURNSTILE_SITE_KEY "$TURNSTILE_SITE_KEY"
step "Copy the Secret Key into a password manager. Part 2 asks for it; don't paste it here."
pause "Saved the Secret Key somewhere safe? Press Enter"

stage "Google sign-in: allow the new address"
say "Sign-in keeps the existing Google OAuth client, which must list the new address before anyone"
say "signs in there. Google can take a few hours to apply it, so do this today, not on the evening."
if confirm "Do you manage the Google Cloud project that holds CSA-ID's OAuth client?"; then
  open_url "https://console.cloud.google.com/apis/credentials"
  step "Pick the project that holds CSA-ID's OAuth client, then select the client under OAuth 2.0 Client IDs."
  step "Under Authorized redirect URIs, select Add URI and enter:"
  say "    $(new_origin)/login/google/callback"
  step "Keep the existing addresses: the old site needs them until the switch. Select Save."
  pause "Saved? Press Enter"
  write_env GOOGLE_REDIRECT_ADDED "$(date +%s)"
else
  SKIPPED+=("Google: ymsrubio adds $(new_origin)/login/google/callback to the OAuth client (run Part 1 again; earlier stages are remembered)")
fi

rm -rf "$empty" "$log"
finish
say "${BOLD}For the pull request${RESET}: all public, and kept in $ENV_FILE"
say "  account_id          $NEW_ACCOUNT_ID"
say "  address             $(new_origin)"
say "  D1 database_id      $NEW_D1_ID"
say "  KV namespace id     $NEW_KV_ID"
say "  Turnstile site key  $TURNSTILE_SITE_KEY"
printf '\n'
}

# ── Part 2 · the evening ──────────────────────────────────────────────────

evening_1() {
stage "Before you start"
say "Run this at the quiet hour you announced, from an up-to-date main."
must "Couldn't reach GitHub to check main." git fetch --quiet origin main
if [[ "$(git rev-parse --abbrev-ref HEAD)" != main || -n "$(git status --porcelain)" ||
      "$(git rev-parse HEAD)" != "$(git rev-parse origin/main)" ]]; then
  warn "Run this from a clean, up-to-date main:  git switch main && git pull"
  exit 1
fi
NEW_ACCOUNT_ID=$(jsonc_values account_id)
NEW_D1_ID=$(jsonc_values database_id)
NEW_KV_ID=$(jsonc_values id)
if ! [[ "$NEW_ACCOUNT_ID" =~ $HEX32 && "$NEW_D1_ID" =~ $UUID && "$NEW_KV_ID" =~ $HEX32 ]] ||
   [[ "$NEW_D1_ID" == "$OLD_D1_ID" || "$NEW_KV_ID" == "$OLD_KV_ID" ]]; then
  warn "main's wrangler.jsonc doesn't point at one new account, database and namespace yet."
  note "The move's pull request has to reach main first (a dev → main release)."
  exit 1
fi
NEW_SUBDOMAIN=$(grep -o -E 'https://csa-id\.[a-z0-9-]+\.workers\.dev' README.md | grep -v yuanmiguelrubio |
  head -n 1 | sed -E 's#https://csa-id\.([a-z0-9-]+)\.workers\.dev#\1#' || true)
if [[ -z "$NEW_SUBDOMAIN" ]] || ! confirm "Is the new address $(new_origin)?"; then
  ask_valid NEW_SUBDOMAIN "The shared account's workers.dev subdomain:" '^[a-z0-9]([a-z0-9-]*[a-z0-9])?$' \
    "Lowercase letters, digits and inner hyphens only."
fi
write_env NEW_SUBDOMAIN "$NEW_SUBDOMAIN" # Part 3 names the new address, on this machine
show "wrangler whoami"
"$WR" whoami || true
say "wrangler.jsonc sends every command to account $NEW_ACCOUNT_ID: the shared team account."
ask_valid OLD_ACCOUNT_ID "ymsrubio's personal account ID (the old one), from the list above:" "$HEX32" \
  "An Account ID is 32 characters of 0-9 and a-f."
if [[ "$OLD_ACCOUNT_ID" == "$NEW_ACCOUNT_ID" ]]; then
  warn "That's the shared account. The old one is where $OLD_ORIGIN runs."
  exit 1
fi
write_env OLD_ACCOUNT_ID "$OLD_ACCOUNT_ID"
write_old_config
load NFC_SLUG SWITCHED_AT OLD_APP_VERSION
open_url "https://dash.cloudflare.com/$OLD_ACCOUNT_ID/workers-and-pages"
step "In the old account, open the csa-id Worker's Settings → Builds: no repository may be connected."
confirm "Is Workers Builds disconnected from the old csa-id Worker?" ||
  { warn "Disconnect it first, so new code can never deploy onto the old database."; exit 1; }
confirm "Did ymsrubio add the new address to the Google OAuth client hours ago (Part 1, stage 6)?" ||
  { warn "Do that first: Google can take a few hours to apply it."; exit 1; }
confirm "Were the Peer Advisers told about tonight, and is nobody in a tutoring session?" ||
  { warn "Pick another evening."; exit 1; }
}

evening_2() {
stage "Old account: count what's there (read only)"
mkdir -p "$OUT"
show "count the rows of every table in the old database"
counts old > "$OUT/counts-old.txt" || { warn "Couldn't read the old database. Is wrangler signed in as ymsrubio?"; exit 1; }
sed 's/^/    /' "$OUT/counts-old.txt"
migration_level old > "$OUT/migrations-old.txt"
say "Migrations applied there: $(tr '\n' ' ' < "$OUT/migrations-old.txt")"
pause
}

evening_3() {
stage "Old account: export the database (read only)"
say "Exports the structure, then every row except the Sessions, as one file for the import."
note "out/ now holds Peer Advisers' names, emails and student numbers. Stage 12 deletes them."
must "The export failed, and nothing changed anywhere. Re-run: bash $0 evening 3" export_db
say "Exported $(grep -c '^INSERT INTO' "$OUT/data.sql") rows from $(wc -l < "$OUT/data-tables.txt" | tr -d ' ') tables."
pause
}

evening_4() {
stage "Old account: export the images (read only)"
must "Copying the images failed, and nothing changed anywhere. Re-run: bash $0 evening 4" export_kv
say "Exported $(kv_count) images, with their content types."
pause
}

evening_5() {
stage "Shared account: import the database"
[[ -f "$OUT/import.sql" ]] || { warn "out/import.sql is missing: run stage 3 first (bash $0 evening 3)."; exit 1; }
if [[ -z "$(app_tables new)" ]]; then
  confirm "Import into the shared account's csa-id database now?" || exit 1
  must "The import failed and changed nothing: it runs all-or-nothing. Fix the error, then: bash $0 evening 5" import_db
elif same_data_as_export new; then
  note "The shared database already holds exactly tonight's export, so the import is skipped."
else
  rm -f "$OUT/data-new-now.sql"
  if [[ -n "$SWITCHED_AT" ]]; then
    warn "The old address already sends people here, so this database is live. Don't empty it."
    exit 1
  fi
  warn "The shared database already holds other data, from an earlier attempt or tonight's migrations."
  confirm "Empty the shared account's csa-id database ($NEW_D1_ID) and import tonight's export?" || exit 1
  must "Emptying the shared database failed." empty_new_db
  must "The import failed and changed nothing. Fix the error, then: bash $0 evening 5" import_db
fi
if ! same_data_as_export new; then
  warn "The shared database doesn't match the export. Rows that differ, per table:"
  changed_tables new
  exit 1
fi
say "The shared database holds exactly the exported rows. Next, main's migrations it doesn't have yet:"
must "A migration failed. Fix it, then: bash $0 evening 5" migrate_new
say "Migrations applied: $(migration_level new | tr '\n' ' ')"
pause
}

evening_6() {
stage "Shared account: import the images"
must "Importing the images failed. Re-run: bash $0 evening 6" import_kv
must "The shared namespace doesn't match the export. Re-run: bash $0 evening 6" verify_kv
say "All $(kv_count) images arrived with the same bytes and content types."
pause
}

evening_7() {
stage "Shared account: deploy the app and set its secrets"
say "Deploys main to $(new_origin). Nobody is sent there until stage 9."
confirm "Build and deploy now?" || exit 1
must "The deploy failed. Fix it, then: bash $0 evening 7" npm run deploy
say "Now the four secrets. They go straight to Cloudflare and are never written to disk."
ask GOOGLE_CLIENT_ID "Google OAuth client ID (the existing client's):"
note "Google Cloud → Credentials → the OAuth client. If its secret isn't saved anywhere, add a new"
note "client secret there; the old site keeps working with its own."
ask_secret GOOGLE_CLIENT_SECRET "Google OAuth client secret:"
ask ADMIN_GOOGLE_SUBS "Administrators' Google subject IDs, comma-separated (the old Worker's value):"
ask_secret TURNSTILE_SECRET_KEY "Turnstile Secret Key (from Part 1):"
show "wrangler secret bulk   (reading the four values from stdin)"
local ok=0
GOOGLE_CLIENT_ID="$GOOGLE_CLIENT_ID" GOOGLE_CLIENT_SECRET="$GOOGLE_CLIENT_SECRET" \
  ADMIN_GOOGLE_SUBS="$ADMIN_GOOGLE_SUBS" TURNSTILE_SECRET_KEY="$TURNSTILE_SECRET_KEY" \
  node -e 'const e = process.env; process.stdout.write(JSON.stringify({ GOOGLE_CLIENT_ID: e.GOOGLE_CLIENT_ID,
    GOOGLE_CLIENT_SECRET: e.GOOGLE_CLIENT_SECRET, ADMIN_GOOGLE_SUBS: e.ADMIN_GOOGLE_SUBS,
    TURNSTILE_SECRET_KEY: e.TURNSTILE_SECRET_KEY }))' | "$WR" secret bulk || ok=$?
unset GOOGLE_CLIENT_SECRET TURNSTILE_SECRET_KEY
((ok == 0)) || { warn "Setting the secrets failed. Re-run: bash $0 evening 7 (deploying again is harmless)"; exit 1; }
pause
}

evening_8() {
stage "Check the new address before anyone is sent there"
counts new > "$OUT/counts-new.txt"
if ! compare_counts "$OUT/counts-old.txt" "$OUT/counts-new.txt"; then
  warn "The row counts differ. Stop here: nothing has switched, and the old site still runs untouched."
  exit 1
fi
ask_valid NFC_SLUG "The Slug written on the NFC Card (like ana-reyes):" '^[a-z0-9-]{3,64}$' \
  "Lowercase letters, digits and hyphens."
write_env NFC_SLUG "$NFC_SLUG"
open_url "$(new_origin)/id/$NFC_SLUG"
step "The Profile shows, with its photo."
open_url "$(new_origin)/login"
step "Select Continue with Google: you land on your own dashboard, with your own Profile."
note "Optional: upload a photo on your own dashboard, then put yours back. It proves uploads work"
note "in the shared account; if they fail, existing photos still show, so decide whether to switch."
if ! confirm "Does everything look right?"; then
  warn "Stop here. Nothing has switched: the old address still serves the old site from its untouched database."
  note "Fix the problem, then run tonight again from stage 5: bash $0 evening 5 (it offers to start over)."
  exit 1
fi
}

evening_9() {
stage "Switch: the old address redirects to the new one"
[[ -n "$NFC_SLUG" ]] || ask_valid NFC_SLUG "The Slug written on the NFC Card:" '^[a-z0-9-]{3,64}$' "Lowercase letters, digits and hyphens."
write_redirect_config
say "Replaces the old account's csa-id Worker with a redirect: every request goes to the same path on"
say "$(new_origin). The app version it replaces stays available for the undo in stage 12."
if [[ -n "$SWITCHED_AT" ]]; then
  # Deploying the redirect again would bury the app's version one step deeper: only re-check.
  note "The redirect is already deployed (switched at $(when "$SWITCHED_AT")), so it isn't deployed again."
else
  confirm "Switch now?" || exit 1
  if [[ -z "$OLD_APP_VERSION" ]]; then
    # Record the app's version id BEFORE the deploy, so stage 12 can roll back to exactly it,
    # even when a crash leaves the redirect deployed without SWITCHED_AT written.
    show "wrangler deployments list --json   (the version the old address serves now)"
    OLD_APP_VERSION=$("$WR" deployments list --json --config "$OUT/redirect.jsonc" | node -e '
      const d = JSON.parse(require("fs").readFileSync(0, "utf8")).sort((a, b) => a.created_on.localeCompare(b.created_on));
      const v = d.length && d[d.length - 1].versions.find((x) => x.percentage === 100);
      if (v) console.log(v.version_id)') || OLD_APP_VERSION=""
    [[ "$OLD_APP_VERSION" =~ ^[0-9a-f-]{36}$ ]] ||
      { warn "Couldn't read the old app's version id. Nothing changed. Re-run: bash $0 evening 9"; exit 1; }
    write_env OLD_APP_VERSION "$OLD_APP_VERSION"
  fi
  say "The app's version, kept for the undo: $OLD_APP_VERSION"
  must "The redirect didn't deploy, and the old site still runs. Re-run: bash $0 evening 9" \
    "$WR" deploy --config "$OUT/redirect.jsonc"
  write_env SWITCHED_AT "$(date +%s)"
fi
show "curl -sI $OLD_ORIGIN/id/$NFC_SLUG"
if curl -sI "$OLD_ORIGIN/id/$NFC_SLUG" | tr -d '\r' | grep -q -i -x "location: $(new_origin)/id/$NFC_SLUG"; then
  say "✓ $OLD_ORIGIN/id/$NFC_SLUG now redirects to the new address."
else
  warn "No redirect seen yet; Cloudflare can take a minute. Check: curl -sI $OLD_ORIGIN/id/$NFC_SLUG"
fi
step "Tap the NFC Card with a phone: it opens the new address."
pause
}

evening_10() {
stage "Old account: was anything written after the export?"
if same_data_as_export old; then
  say "✓ Nothing changed in the old database since the export: no edits were lost."
else
  warn "These tables changed in the old database after the export (row lines that differ):"
  changed_tables old
  note "out/changes-old.diff has the exact rows ('<' as exported, '>' as now). Re-enter those edits"
  note "on the new site, or undo in stage 12 and run the move again another evening."
fi
pause
}

evening_11() {
stage "Shared account: connect Workers Builds"
say "So merges to main deploy again and pull requests get previews. This can wait until tomorrow."
open_url "https://dash.cloudflare.com/$NEW_ACCOUNT_ID/workers-and-pages"
step "Select csa-id → Settings → Builds → Connect, then the GitHub repository isayulee/CSA-ID."
note "GitHub may ask isayulee to approve Cloudflare's app for the repository."
step "Copy the build settings from the old account's csa-id Worker (same page there). Expected:"
say "    branch main · build: npx opennextjs-cloudflare build · deploy: npx opennextjs-cloudflare deploy"
say "    preview: npx wrangler preview"
note "The first build runs on the next push to the repository."
if confirm "Connected?"; then
  write_env BUILDS_CONNECTED "$(date +%s)"
else
  SKIPPED+=("Connect Workers Builds in the shared account: until then, merges to main don't deploy")
fi
}

evening_12() {
stage "Keep or undo"
[[ -n "$SWITCHED_AT" ]] && say "Switched at $(when "$SWITCHED_AT"). Decide within 30 minutes of that."
say "After 30 minutes an undo would throw away edits made on the new site; fix problems going forward."
if confirm "Keep the move?"; then
  write_env KEPT_AT "$(date +%s)"
  say "✓ Kept. In 7 days, delete the old database and namespace: bash $0 cleanup"
else
  confirm "Undo: roll the old csa-id Worker back to the app, on its untouched database?" || exit 1
  if [[ -z "$OLD_APP_VERSION" ]]; then
    warn "No app version was recorded. Find it: npx wrangler deployments list --config $OUT/redirect.jsonc"
    note "Then: npx wrangler rollback <the version before the redirect> --config $OUT/redirect.jsonc"
    exit 1
  fi
  must "The rollback failed. Try: npx wrangler rollback $OLD_APP_VERSION --config $OUT/redirect.jsonc" \
    "$WR" rollback "$OLD_APP_VERSION" --config "$OUT/redirect.jsonc" -m "Undo the move to the shared account"
  write_env SWITCHED_AT ""
  write_env OLD_APP_VERSION ""
  say "✓ The old address serves the old site again."
  note "The shared account keeps tonight's copy, unused. To try again another evening: bash $0 evening"
  note "(stage 5 empties the shared database first)."
fi
# Either way, tonight's exports have done their job: they hold personal data, so they go now.
rm -rf "$OUT/schema.sql" "$OUT/data.sql" "$OUT/import.sql" "$OUT/kv" "$OUT"/data-*-now.sql "$OUT"/changes-*.diff
say "✓ Deleted tonight's exports from out/ (the counts and configs stay for Part 3)."
finish
}

evening() {
local from="$1" i
[[ "$from" =~ ^([1-9]|1[0-2])$ ]] || { warn "The stage to resume from is 1 to 12."; exit 2; }
TOTAL_STAGES=12
# Every command here names its account through a config's account_id; an inherited variable must not redirect one.
unset CLOUDFLARE_ACCOUNT_ID CF_ACCOUNT_ID
banner "CSA-ID move · Part 2 of 3: the evening"
evening_1 # always: it loads tonight's values and checks where commands go
for ((i = from > 2 ? from : 2; i <= 12; i++)); do
  _STAGE_INDEX=$((i - 1))
  "evening_$i"
done
}

# ── Part 3 · clean up ─────────────────────────────────────────────────────

cleanup() {
TOTAL_STAGES=3
unset CLOUDFLARE_ACCOUNT_ID CF_ACCOUNT_ID # as in evening: the configs name the account
banner "CSA-ID move · Part 3 of 3: clean up the old account"
load OLD_ACCOUNT_ID KEPT_AT NEW_SUBDOMAIN

stage "Before you delete anything"
if [[ -z "$KEPT_AT" || -z "$OLD_ACCOUNT_ID" ]]; then
  warn "No kept move is recorded on this machine. Run this where Part 2 ran."
  exit 1
fi
local days=$(( ($(date +%s) - KEPT_AT) / 86400 ))
say "The move was kept $days day(s) ago, on $(when "$KEPT_AT")."
if ((days < 7)); then
  warn "Wait the full 7 days: until then the old database is the fallback."
  confirm "Delete it anyway?" || exit 1
fi
confirm "Has the new site worked all week, with nobody asking to undo?" || exit 1
write_old_config

stage "Delete the old database and image namespace"
say "This deletes the Peer Advisers' data from ymsrubio's personal account, for good. The shared"
say "account's copy becomes the only one. It can't be undone."
ask CONFIRM_DELETE "Type delete to confirm:" || exit 1
[[ "$CONFIRM_DELETE" == delete ]] || { warn "Nothing deleted."; exit 1; }
must "Deleting the old database failed." "$WR" d1 delete csa-id --config "$OLD_CFG"
must "Deleting the old namespace failed." "$WR" kv namespace delete --namespace-id "$OLD_KV_ID" --config "$OLD_CFG"

stage "What's left"
rm -rf "$OUT"
say "✓ Deleted this machine's leftovers (out/)."
say "The redirect at $OLD_ORIGIN stays until every NFC Card holds $(new_origin)."
say "After the last card is rewritten, delete it: old account → Workers & Pages → csa-id → Settings."
say "Then open a pull request that deletes scripts/move-to-shared-account/."
finish
}

run_wizard() {
ENV_FILE="$HERE/.move.env"
cd "$REPO"
case "${1:-}" in
  prepare) prepare ;;
  evening) evening "${2:-1}" ;;
  cleanup) cleanup ;;
  *) printf 'Usage: bash %s prepare | evening [stage to resume from] | cleanup\n' "$0"; exit 2 ;;
esac
}

run_wizard "$@"; exit
